import{_ as t,H as a,f as l,i as o}from"./chunks/framework.DLd0CbzH.js";const h=JSON.parse('{"title":"Продажи (Чеки)","description":"Оформление продаж через POS-терминал, учет каналов сбыта, логистики и расчет рейтинга маржинальности (Time ROI).","frontmatter":{"title":"Продажи (Чеки)","description":"Оформление продаж через POS-терминал, учет каналов сбыта, логистики и расчет рейтинга маржинальности (Time ROI).","order":9},"headers":[],"relativePath":"ru/docs/spaces/production/sales.md","filePath":"ru/docs/spaces/production/sales.md"}'),i={name:"ru/docs/spaces/production/sales.md"};function r(s,e,n,p,c,m){return a(),l("div",null,[...e[0]||(e[0]=[o('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🧾-продажи-pos-терминал-и-анализ-эффективности" tabindex="-1">🧾 Продажи: POS-терминал и анализ эффективности <a class="header-anchor" href="#🧾-продажи-pos-терминал-и-анализ-эффективности" aria-label="Permalink to &quot;🧾 Продажи: POS-терминал и анализ эффективности&quot;">​</a></h1><p>Вкладка <strong>«Продажи»</strong> разделена на три функциональные зоны: форму оформления новой сделки (POS-терминал), интерактивный журнал пробитых чеков и аналитическую таблицу окупаемости вашего рабочего времени.</p><p>Проведение продажи в программе — это ключевое действие, которое мгновенно списывает готовый товар с витрины, зачисляет деньги в ДДС и рассчитывает чистую прибыль.</p><hr><h2 id="🖥️-оформление-сделки-pos-терминал" tabindex="-1">🖥️ Оформление сделки (POS-терминал) <a class="header-anchor" href="#🖥️-оформление-сделки-pos-терминал" aria-label="Permalink to &quot;🖥️ Оформление сделки (POS-терминал)&quot;">​</a></h2><p>Форма в верхней части экрана позволяет быстро провести продажу. Для этого заполняются следующие поля:</p><ol><li><strong>Выбор товара:</strong> В списке отображаются только те изделия, которые сейчас физически есть на складе готовой продукции (остаток &gt; 0).</li><li><strong>Канал продаж:</strong> Через какой ресурс совершена сделка (например, <em>Ярмарка Мастеров, личный сайт, соцсети, маркетплейс</em>). От выбора канала зависит итоговая розничная цена.</li><li><strong>Количество:</strong> Сколько штук приобретает клиент.</li><li><strong>Доставка (Логистика):</strong> Тонкий экономический инструмент, который программа рассчитывает по строгим правилам.</li></ol><h3 id="🚚-экономическая-логика-доставки" tabindex="-1">🚚 Экономическая логика доставки <a class="header-anchor" href="#🚚-экономическая-логика-доставки" aria-label="Permalink to &quot;🚚 Экономическая логика доставки&quot;">​</a></h3><p>Программа предлагает на выбор два режима оплаты логистики, которые по-разному влияют на ваши финансы:</p><ul><li><strong>Режим «Платит Покупатель» (Клиент):</strong> Клиент перевел вам деньги за товар и отдельно компенсировал стоимость доставки. <ul><li><em>В ДДС (Касса):</em> Запишется полный приход (Стоимость товара + Стоимость доставки).</li><li><em>Расход:</em> Запишется расход на доставку.</li><li><em>Влияние на прибыль:</em> Нулевое (сколько получили за доставку, столько и потратили на отправку). Но в кассе (ДДС) при этом отразится абсолютно точный оборот живых денег.</li></ul></li><li><strong>Режим «Платит Мастерская» (Расход):</strong> Вы предоставили клиенту бесплатную доставку (или сделали её за свой счет). <ul><li><em>В ДДС (Касса):</em> Запишется чистый приход за товар. И запишется расход на доставку транспортной компании.</li><li><em>Влияние на прибыль:</em> Отрицательное. Стоимость доставки будет напрямую вычтена из вашей чистой прибыли по этой сделке.</li></ul></li></ul><hr><h2 id="📈-управление-каналами-сбыта" tabindex="-1">📈 Управление каналами сбыта <a class="header-anchor" href="#📈-управление-каналами-сбыта" aria-label="Permalink to &quot;📈 Управление каналами сбыта&quot;">​</a></h2><p>Разные площадки берут разные комиссии и требуют разного позиционирования. В программе вы можете настроить индивидуальные наценки для каждого канала.</p><p>Нажмите иконку шестеренки ⚙️ рядом с выбором канала, чтобы открыть окно управления:</p><ul><li>Вы можете добавить новый канал (например, <em>«Авито»</em> или <em>«Озон»</em>).</li><li>Указать для него <strong>индивидуальную наценку в %</strong> (она прибавится к базовой рекомендуемой розничной цене из Калькулятора).</li></ul><div class="tip custom-block"><p class="custom-block-title">Фиксированные цены под конкретный канал</p><p>Если наценка в процентах вам не подходит и вы хотите установить на товар строгую твердую цену для конкретной площадки (например, на маркетплейсе товар должен стоить ровно 4 500 ₽, а на маркете — 4 000 ₽), вы можете сделать это на вкладке <a href="./showcase">«Товары»</a>, задав фиксированные цены в паспорте товара. В этом случае калькулятор уступит место вашему ручному решению.</p></div><hr><h2 id="🧾-история-чеков-журнал-продаж" tabindex="-1">🧾 История чеков (Журнал продаж) <a class="header-anchor" href="#🧾-история-чеков-журнал-продаж" aria-label="Permalink to &quot;🧾 История чеков (Журнал продаж)&quot;">​</a></h2><p>В левой нижней части экрана расположен журнал всех проведенных продаж.</p><ul><li>Таблица выводит дату сделки, канал сбыта, название изделия, количество и <strong>чистую прибыль</strong> по каждому чеку.</li><li>Таблица поддерживает пагинацию (постраничный просмотр по 15 записей), что гарантирует быструю и плавную работу интерфейса даже при тысячах продаж в базе.</li></ul><hr><h2 id="🏆-реитинг-изделии-time-roi-—-маржинальность-времени" tabindex="-1">🏆 Рейтинг изделий (Time ROI — Маржинальность времени) <a class="header-anchor" href="#🏆-реитинг-изделии-time-roi-—-маржинальность-времени" aria-label="Permalink to &quot;🏆 Рейтинг изделий (Time ROI — Маржинальность времени)&quot;">​</a></h2><p>В правой нижней части экрана находится одна из самых ценных таблиц для собственника бизнеса — <strong>Рейтинг изделий по окупаемости времени</strong>.</p><p>Обычный учет показывает только абсолютную прибыль (например, вы продали сумку и заработали 5 000 ₽, а на обложке для паспорта заработали 1 000 ₽). Это создает иллюзию, что шить сумки выгоднее.</p><p><strong>ОмниКрафт ЕРП считает Time ROI (прибыль в час):</strong> Программа берет чистую прибыль от продажи товара и делит её на количество часов, которые вы физически потратили на изготовление (на базе нормы времени из Калькулятора).</p><p>$$\\text{Прибыль в час (Time ROI)} = \\frac{\\text{Чистая прибыль от продаж изделия}}{\\text{Всего затрачено часов на пошив сданных позиций}}$$</p><h3 id="зачем-это-нужно" tabindex="-1">Зачем это нужно? <a class="header-anchor" href="#зачем-это-нужно" aria-label="Permalink to &quot;Зачем это нужно?&quot;">​</a></h3><p>Эта таблица наглядно покажет вам «скрытых убийц» вашего времени и настоящие золотые жилы:</p><ul><li>Вы можете обнаружить, что сложная сумка приносит вам <strong>300 ₽ в час</strong> из-за огромных трудозатрат.</li><li>А простая обложка для паспорта приносит <strong>1 500 ₽ в час</strong>, так как шьется за 20 минут.</li><li><em>Вывод бизнеса:</em> Чтобы зарабатывать больше, вам экономически выгоднее сосредоточиться на массовых продажах обложек, а цену на сумку нужно срочно поднимать в Калькуляторе.</li></ul>',30)])])}const u=t(i,[["render",r]]);export{h as __pageData,u as default};
